<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { useRoute } from 'vue-router';
import AppTabs from '../components/AppTabs.vue';
import LoadingBlock from '../components/LoadingBlock.vue';
import PageHeading from '../components/PageHeading.vue';
import StatusPill from '../components/StatusPill.vue';
import { api, apiMessage } from '../lib/api';

const route = useRoute();
const workplan = ref(null); const options = ref({ departments: [], staff: [] }); const error = ref(''); const saving = ref(false); const tab = ref('structure');
const selectedActivityId = ref(null); const selectedIndicatorId = ref(null);
const objective = reactive({ code: '', title: '', description: '', department_id: '', priority: '', performance_weight: '', sort_order: 0 });
const activity = reactive({ activity_code: '', title: '', description: '', expected_output: '', department_id: '', responsible_staff_id: '', start_date: '', end_date: '', planned_cost: '', funding_source: '', status: 'not_started', performance_weight: '', remarks: '', sort_order: 0 });
const indicator = reactive({ code: '', indicator: '', unit: '', baseline_value: '', annual_target_value: '', target_mode: 'absolute', direction: 'increase', weight: 1, is_required: true, sort_order: 0 });
const targets = reactive({ q1: '', q2: '', q3: '', q4: '', annual: '' }); const supportingStaffIds = ref([]);
const tabs = [{ id: 'structure', label: 'Objectives & activities' }, { id: 'guidance', label: 'Draft guidance' }];
const editable = computed(() => ['draft', 'returned'].includes(workplan.value?.status) && workplan.value?.can?.update);
const selectedActivity = computed(() => workplan.value?.objectives.flatMap((item) => item.activities).find((item) => item.id === selectedActivityId.value) ?? null);
const selectedIndicator = computed(() => selectedActivity.value?.indicators.find((item) => item.id === selectedIndicatorId.value) ?? null);
const activityStaff = computed(() => options.value.staff.filter((staff) => !activity.department_id || Number(staff.department_id) === Number(activity.department_id)));
const supportOptions = computed(() => options.value.staff.filter((staff) => staff.id !== Number(selectedActivity.value?.responsible_staff?.id)));
const load = async () => { try { const response = await api.get(`/workplans/${route.params.id}`); workplan.value = response.data.data; options.value = response.data.options ?? options.value; } catch (e) { error.value = apiMessage(e); } };
const resetActivity = () => Object.assign(activity, { activity_code: '', title: '', description: '', expected_output: '', department_id: '', responsible_staff_id: '', start_date: '', end_date: '', planned_cost: '', funding_source: '', status: 'not_started', performance_weight: '', remarks: '', sort_order: 0 });
const selectActivity = (row) => { selectedActivityId.value = row.id; selectedIndicatorId.value = null; supportingStaffIds.value = row.supporting_staff.map((staff) => staff.id); Object.assign(activity, { activity_code: row.activity_code, title: row.title, description: row.description ?? '', expected_output: row.expected_output ?? '', department_id: row.department?.id ?? '', responsible_staff_id: row.responsible_staff?.id ?? '', start_date: row.start_date, end_date: row.end_date, planned_cost: row.planned_cost ?? '', funding_source: row.funding_source ?? '', status: row.status, performance_weight: row.performance_weight ?? '', remarks: row.remarks ?? '', sort_order: row.sort_order }); };
const selectIndicator = (row) => { selectedIndicatorId.value = row.id; Object.assign(indicator, { code: row.code, indicator: row.indicator, unit: row.unit ?? '', baseline_value: row.baseline_value ?? '', annual_target_value: row.annual_target_value ?? '', target_mode: row.target_mode, direction: row.direction, weight: row.weight, is_required: row.is_required, sort_order: row.sort_order }); Object.keys(targets).forEach((period) => { targets[period] = row.targets.find((target) => target.period === period)?.target_value ?? ''; }); };
const request = async (action) => { saving.value = true; error.value = ''; try { await action(); await load(); } catch (e) { error.value = apiMessage(e); } finally { saving.value = false; } };
const addObjective = () => request(async () => { await api.post(`/workplans/${workplan.value.id}/objectives`, objective); Object.assign(objective, { code: '', title: '', description: '', department_id: '', priority: '', performance_weight: '', sort_order: 0 }); });
const saveActivity = (objectiveId) => request(async () => { if (selectedActivityId.value) await api.put(`/workplan-activities/${selectedActivityId.value}`, activity); else await api.post(`/workplan-objectives/${objectiveId}/activities`, activity); });
const saveSupport = () => request(() => api.put(`/workplan-activities/${selectedActivityId.value}/supporting-staff`, { staff_ids: supportingStaffIds.value }));
const saveIndicator = () => request(async () => { if (selectedIndicatorId.value) await api.put(`/workplan-indicators/${selectedIndicatorId.value}`, indicator); else { const response = await api.post(`/workplan-activities/${selectedActivityId.value}/indicators`, indicator); selectedIndicatorId.value = response.data.data.id; } });
const saveTargets = () => request(() => api.put(`/workplan-indicators/${selectedIndicatorId.value}/targets`, { targets: Object.entries(targets).map(([period, target_value]) => ({ period, target_value: target_value === '' ? null : target_value })) }));
onMounted(load);
</script>

<template>
    <PageHeading eyebrow="Draft authoring" :title="workplan?.title ?? 'Workplan editor'"><RouterLink class="civic-button" :to="`/workplans/${route.params.id}`">View plan</RouterLink></PageHeading>
    <div v-if="error" class="civic-error">{{ error }}</div><LoadingBlock v-else-if="!workplan" />
    <template v-else>
        <section class="civic-workspace"><div class="civic-section-heading"><div><span class="civic-kicker">{{ workplan.mda?.name }} · {{ workplan.year }}</span><h2>Revision {{ workplan.revision_no }}</h2></div><StatusPill :status="workplan.status" /></div><AppTabs v-model="tab" :tabs="tabs" /></section>
        <section v-if="tab === 'structure'" class="civic-workspace civic-workplan-authoring">
            <div v-if="!editable" class="civic-error">Only draft or returned workplans can be structurally edited.</div>
            <details v-if="editable" open><summary>Add objective</summary><form class="civic-form-grid" @submit.prevent="addObjective"><label class="civic-field"><span>Code</span><input v-model="objective.code" required></label><label class="civic-field"><span>Title</span><input v-model="objective.title" required></label><label class="civic-field"><span>Department</span><select v-model="objective.department_id"><option value="">MDA-wide objective</option><option v-for="department in options.departments" :key="department.id" :value="department.id">{{ department.code }} - {{ department.name }}</option></select></label><label class="civic-field"><span>Priority</span><input v-model="objective.priority"></label><label class="civic-field civic-field-wide"><span>Description</span><textarea v-model="objective.description" rows="2" /></label><button class="civic-button civic-button-primary" :disabled="saving">Add objective</button></form></details>
            <article v-for="item in workplan.objectives" :key="item.id" class="civic-workspace"><h3>{{ item.code }} · {{ item.title }}</h3><p>{{ item.department?.name ?? 'MDA-wide' }}</p>
                <button v-for="row in item.activities" :key="row.id" class="civic-record-link" type="button" @click="selectActivity(row)">{{ row.activity_code }} · {{ row.title }} — {{ row.responsible_staff?.full_name || 'Unassigned' }}</button>
                <details v-if="editable" :open="selectedActivity?.workplan_objective_id === item.id"><summary>{{ selectedActivity ? 'Edit selected activity' : 'Add activity' }}</summary><form class="civic-form-grid" @submit.prevent="saveActivity(item.id)"><label class="civic-field"><span>Activity code</span><input v-model="activity.activity_code" required></label><label class="civic-field"><span>Activity title</span><input v-model="activity.title" required></label><label class="civic-field civic-field-wide"><span>Description</span><textarea v-model="activity.description" rows="2" /></label><label class="civic-field civic-field-wide"><span>Expected output</span><textarea v-model="activity.expected_output" rows="2" /></label><label class="civic-field"><span>Department</span><select v-model="activity.department_id"><option value="">MDA-wide activity</option><option v-for="department in options.departments" :key="department.id" :value="department.id">{{ department.code }} - {{ department.name }}</option></select></label><label class="civic-field"><span>Responsible officer</span><select v-model="activity.responsible_staff_id"><option value="">Unassigned</option><option v-for="staff in activityStaff" :key="staff.id" :value="staff.id">{{ staff.full_name }} ({{ staff.staff_number }}) — {{ staff.department || 'No department' }}{{ staff.rank ? `, ${staff.rank}` : '' }}</option></select><small>Departmental activities require the officer’s current department to match.</small></label><label class="civic-field"><span>Start date</span><input v-model="activity.start_date" type="date" required></label><label class="civic-field"><span>End date</span><input v-model="activity.end_date" type="date" required></label><label class="civic-field"><span>Planned cost</span><input v-model="activity.planned_cost" type="number" min="0" step="0.01"></label><label class="civic-field"><span>Funding source</span><input v-model="activity.funding_source"></label><label class="civic-field"><span>Performance weight</span><input v-model="activity.performance_weight" type="number" min="0.0001" step="0.0001"></label><label class="civic-field civic-field-wide"><span>Remarks</span><textarea v-model="activity.remarks" rows="2" /></label><button class="civic-button civic-button-primary" :disabled="saving">{{ selectedActivityId ? 'Save activity' : 'Add activity' }}</button><button v-if="selectedActivityId" class="civic-button" type="button" @click="selectedActivityId = null; resetActivity()">New activity</button></form></details>
            </article>
            <section v-if="selectedActivity" class="civic-workspace"><h3>{{ selectedActivity.activity_code }} · staff and indicators</h3><details v-if="editable" open><summary>Supporting staff</summary><p>Supporting staff assist delivery; the responsible officer remains accountable.</p><select v-model="supportingStaffIds" multiple class="civic-select-multi"><option v-for="staff in supportOptions" :key="staff.id" :value="staff.id">{{ staff.full_name }} ({{ staff.staff_number }}) — {{ staff.department || 'No department' }}</option></select><p><button class="civic-button civic-button-primary" :disabled="saving" @click="saveSupport">Save supporting staff</button></p></details><details v-if="editable" open><summary>Indicators and cumulative targets</summary><button v-for="row in selectedActivity.indicators" :key="row.id" class="civic-record-link" type="button" @click="selectIndicator(row)">{{ row.code }} · {{ row.indicator }}</button><form class="civic-form-grid" @submit.prevent="saveIndicator"><label class="civic-field"><span>Code</span><input v-model="indicator.code" required></label><label class="civic-field"><span>Indicator</span><input v-model="indicator.indicator" required></label><label class="civic-field"><span>Unit</span><input v-model="indicator.unit"></label><label class="civic-field"><span>Baseline</span><input v-model="indicator.baseline_value" type="number" step="0.0001"></label><label class="civic-field"><span>Annual target</span><input v-model="indicator.annual_target_value" type="number" step="0.0001"></label><label class="civic-field"><span>Target mode</span><select v-model="indicator.target_mode"><option value="absolute">Absolute target</option><option value="increase_from_baseline">Increase from baseline</option><option value="decrease_from_baseline">Decrease from baseline</option><option value="milestone">Milestone</option></select></label><label class="civic-field"><span>Direction</span><select v-model="indicator.direction"><option value="increase">Higher is better</option><option value="decrease">Lower is better</option><option value="milestone">Milestone</option></select></label><label class="civic-field"><span>Weight</span><input v-model="indicator.weight" type="number" min="0.0001" step="0.0001" required></label><label class="civic-field"><span>Required</span><input v-model="indicator.is_required" type="checkbox"></label><button class="civic-button civic-button-primary" :disabled="saving">{{ selectedIndicatorId ? 'Save indicator' : 'Add indicator' }}</button></form><form v-if="selectedIndicatorId" class="civic-form-grid" @submit.prevent="saveTargets"><p class="civic-field-wide"><strong>Cumulative targets:</strong> each quarterly amount is the target achieved by the end of that quarter.</p><label v-for="period in ['q1','q2','q3','q4','annual']" :key="period" class="civic-field"><span>{{ period.toUpperCase() }}</span><input v-model="targets[period]" type="number" step="0.0001"></label><button class="civic-button civic-button-primary" :disabled="saving">Save cumulative targets</button></form></details></section>
        </section>
        <section v-else class="civic-workspace civic-workplan-guidance">
            <div class="civic-section-heading"><div><span class="civic-kicker">Use before submission</span><h3>Annual Workplan authoring guide</h3></div></div>
            <p>A Workplan is the approved baseline against which later progress is reported. Build it from the strategic result down to measurable delivery: <strong>Objective → Activity → Indicator → cumulative period targets</strong>. Add only commitments that this MDA can account for during {{ workplan.year }}.</p>

            <details open>
                <summary><strong>1. Start with a clear objective</strong></summary>
                <p>An objective describes the outcome or service improvement to be achieved, not a routine task. Assign it to the owning department where one department is accountable; leave it MDA-wide only when it genuinely spans the organisation.</p>
                <div class="civic-table-wrap"><table class="civic-table"><thead><tr><th>Avoid</th><th>Use instead</th></tr></thead><tbody><tr><td>Conduct supervision</td><td><strong>Improve quality and coverage of primary health-care supervision.</strong></td></tr><tr><td>Buy medicines</td><td><strong>Improve availability of essential medicines in supported facilities.</strong></td></tr></tbody></table></div>
                <p><strong>Example:</strong> Code <code>OBJ-01</code>; title <em>Improve quality and coverage of primary health-care supervision</em>; department <em>Medical Services</em>; priority <em>High</em>.</p>
            </details>

            <details>
                <summary><strong>2. Add delivery activities under each objective</strong></summary>
                <p>An activity is a specific, deliverable piece of work. Give it a realistic period, expected output, department, planned operational cost where known, one responsible officer, and any supporting staff.</p>
                <p><strong>Worked example:</strong></p>
                <div class="civic-table-wrap"><table class="civic-table"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td>Activity code / title</td><td><code>ACT-01</code> - Conduct quarterly supportive supervision of PHC facilities</td></tr><tr><td>Expected output</td><td>Quarterly supervision visits completed and findings communicated to facilities</td></tr><tr><td>Period</td><td>1 January {{ workplan.year }} - 31 December {{ workplan.year }}</td></tr><tr><td>Responsible officer</td><td>Director, Medical Services (the accountable officer)</td></tr><tr><td>Supporting staff</td><td>Monitoring Officer; PHC Coordinator (contributors, not substitutes for accountability)</td></tr><tr><td>Planned cost / source</td><td>₦2,400,000 / MDA operational allocation</td></tr></tbody></table></div>
                <p>Use <strong>Supporting staff</strong> only for colleagues who materially assist delivery. The responsible officer remains the business owner of the activity.</p>
            </details>

            <details>
                <summary><strong>3. Define indicators that can be verified</strong></summary>
                <p>An indicator tells the system how achievement will be measured. State the thing being measured, its unit, baseline (where relevant), target mode, direction, and weight. Avoid vague indicators such as “improved service delivery”.</p>
                <div class="civic-table-wrap"><table class="civic-table"><thead><tr><th>Activity</th><th>Good indicator</th><th>Unit</th><th>Mode / direction</th></tr></thead><tbody><tr><td>Quarterly PHC supervision</td><td>PHC facilities supervised</td><td>Facilities</td><td>Absolute / higher is better</td></tr><tr><td>Medicine availability</td><td>Stock-out rate for tracer medicines</td><td>Percent</td><td>Decrease from baseline / lower is better</td></tr><tr><td>Policy development</td><td>Supervision guideline approved</td><td>Completion</td><td>Milestone</td></tr></tbody></table></div>
                <p><strong>Target-mode examples:</strong> <em>Absolute</em>: 100 facilities supervised. <em>Increase from baseline</em>: raise facility reporting completeness from a baseline of 60%. <em>Decrease from baseline</em>: reduce stock-out rate from 18%. <em>Milestone</em>: use 1 for achieved and 0 for not achieved; do not enter invented partial percentages.</p>
            </details>

            <details>
                <summary><strong>4. Enter cumulative, not incremental, quarterly targets</strong></summary>
                <p>Quarterly targets mean the total expected achievement <strong>by the end of each quarter</strong>. They are not additional amounts for that quarter. Annual is a separate reporting period and should be entered deliberately, even if it equals Q4.</p>
                <div class="civic-table-wrap"><table class="civic-table"><thead><tr><th>Indicator: PHC facilities supervised</th><th>Correct cumulative target</th><th>Meaning</th></tr></thead><tbody><tr><td>Q1</td><td>25</td><td>25 facilities supervised by 31 March</td></tr><tr><td>Q2</td><td>50</td><td>50 total facilities supervised by 30 June, not 25 + 50</td></tr><tr><td>Q3</td><td>75</td><td>75 total facilities supervised by 30 September</td></tr><tr><td>Q4</td><td>100</td><td>100 total facilities supervised by 31 December</td></tr><tr><td>Annual</td><td>100</td><td>Annual report target; entered separately from Q4</td></tr></tbody></table></div>
                <p>When reporting later, actuals follow the same rule. For example, Q1 actual <strong>22</strong> and Q2 actual <strong>47</strong> means 47 facilities have been supervised in total by the end of Q2.</p>
            </details>

            <details>
                <summary><strong>5. Use weights carefully</strong></summary>
                <p>Weights express relative importance for performance aggregation. They do not need to total exactly 100 because the system normalizes eligible weights, but use a consistent approach within an objective.</p>
                <p><strong>Example:</strong> an objective has three activities weighted 50, 30 and 20. If their official achievement is 100%, 80% and 0%, the objective achievement is <code>(50×1.00 + 30×0.80 + 20×0.00) / (50+30+20) = 74%</code>. Missing verified reports therefore affect achievement; they are not silently ignored.</p>
            </details>

            <details>
                <summary><strong>6. Check this before submission</strong></summary>
                <ul><li>Every objective has a meaningful result statement and the correct department/MDA ownership.</li><li>Every activity has dates, an expected output, an accountable responsible officer, and an appropriate department.</li><li>Every indicator has a clear unit, target mode, direction, weight, and applicable Q1-Q4/Annual target.</li><li>Quarterly values are cumulative and do not fall from one quarter to the next unless the indicator methodology explicitly requires it.</li><li>Milestones use a verifiable achieved/not-achieved target, not subjective percentages.</li><li>Planned costs are operational planning estimates; do not use this Workplan to modify payroll or budget workbooks.</li><li>Review the plan in <strong>View plan</strong>, then submit it. A submitted plan is locked until returned for correction; only an approved, activated revision accepts new progress reports.</li></ul>
            </details>
        </section>
    </template>
</template>
